<template>
  <q-page class="setup-page">
    <main class="setup-shell">
      <q-stepper v-model="currentStep" color="teal-9" active-color="teal-9" done-color="teal-9" animated flat alternative-labels class="setup-stepper">
        <q-step :name="1" title="About" icon="home" :done="currentStep > 1">
        <section class="step-content">
          <div class="step-copy"><span class="step-kicker">Building details</span><h2>About the accommodation</h2><p>Describe the building first. You will add rentable rooms and their details separately.</p></div>
          <label>Accommodation name <span>*</span><q-input v-model="form.name" outlined placeholder="e.g. Sunrise Student Residence" :error="!!stepError.name" :error-message="stepError.name" /></label>
          <label>Accommodation type <span>*</span><q-select v-model="form.accommodationType" :options="accommodationTypes" outlined emit-value map-options :error="!!stepError.accommodationType" :error-message="stepError.accommodationType" /></label>
          <label v-if="form.accommodationType === 'other'">Describe the accommodation type <span>*</span><q-input v-model="form.customAccommodationType" outlined placeholder="e.g. Mixed-use residence" /></label>
          <fieldset><legend>Who can stay <span>*</span></legend><div class="choice-grid"><button v-for="option in genderOptions" :key="option.value" type="button" :class="{ active: form.genderPolicy === option.value }" :aria-pressed="form.genderPolicy === option.value" @click="form.genderPolicy = option.value">{{ option.label }}</button></div><p v-if="stepError.genderPolicy" class="field-error">{{ stepError.genderPolicy }}</p></fieldset>
          <label>Number of floors <span class="optional">Optional</span><q-input v-model.number="form.totalFloors" outlined type="number" min="1" inputmode="numeric" placeholder="e.g. 3" /></label>
          <label>Short description <span>*</span><q-input v-model="form.description" outlined type="textarea" rows="4" placeholder="Describe the accommodation, location, and what residents should know." :error="!!stepError.description" :error-message="stepError.description" /></label>
        </section>
        </q-step>

        <q-step :name="2" title="Exterior" icon="photo_camera" :done="currentStep > 2">
        <section class="step-content">
          <div class="step-copy"><span class="step-kicker">Optional photos</span><h2>Exterior and arrival</h2><p>Show the exterior, entrance, signage, or parking so students can recognize the accommodation.</p></div>
          <PhotoPicker label="Add exterior photos" hint="Optional. The first image will be the accommodation cover." :photos="form.exteriorImages" show-cover @select="onPhotosSelected($event, form.exteriorImages)" @remove="removePhoto(form.exteriorImages, $event)" />
        </section>
        </q-step>

        <q-step :name="3" title="Location" icon="location_on" :done="currentStep > 3">
        <section class="step-content">
          <div class="step-copy"><span class="step-kicker">Required location</span><h2>Pin the accommodation</h2><p>Search the address, select a result, then adjust the pin on the map if needed.</p></div>
          <label>Full address <span>*</span><q-input v-model="form.address" outlined type="textarea" rows="2" placeholder="Building, street, barangay, city" :error="!!stepError.address" :error-message="stepError.address" @update:model-value="searchLocation" /></label>
          <div v-if="locationSearchLoading" class="map-status">Searching Mapbox...</div>
          <div v-else-if="locationResults.length" class="location-results"><button v-for="result in locationResults" :key="result.id" type="button" @click="selectLocation(result)"><IconifyIcon icon="lucide:map-pin" width="16" /><span><strong>{{ result.name }}</strong><small>{{ result.address }}</small></span></button></div>
          <div ref="locationMap" class="location-map" aria-label="Map used to set the accommodation location" />
          <p class="map-hint">Tap the map to place or adjust the accommodation pin.</p>
        </section>
        </q-step>

        <q-step :name="4" title="Permits" icon="verified_user" :done="currentStep > 4">
        <section class="step-content">
          <div class="step-copy"><span class="step-kicker">Required for accreditation</span><h2>Submit accommodation permits</h2><p>OSAS must verify the accommodation before you can add rentable rooms. Submit clear, current copies of all four permits.</p></div>
          <section class="permit-list" aria-describedby="permit-help"><p id="permit-help" class="sr-only">All four documents are required to submit this accommodation for verification.</p><label v-for="permit in permitRequirements" :key="permit.type" class="permit-item"><span class="permit-icon"><IconifyIcon :icon="permit.icon" width="20" aria-hidden="true" /></span><span><strong>{{ permit.label }} <b>*</b></strong><small>{{ permit.description }}</small></span><q-file v-model="form.permits[permit.type]" outlined dense accept="image/jpeg,image/png,image/webp,application/pdf" :aria-label="`Upload ${permit.label}`"><template #prepend><IconifyIcon icon="lucide:upload" width="17" /></template><template #append><IconifyIcon v-if="form.permits[permit.type]" icon="lucide:check-circle-2" width="18" class="upload-complete" /></template></q-file></label></section>
          <p v-if="stepError.permits" class="field-error">{{ stepError.permits }}</p>
        </section>
        </q-step>

        <q-step :name="5" title="Review" icon="fact_check">
        <section class="step-content">
          <div class="step-copy"><span class="step-kicker">Ready for review</span><h2>Rules and review</h2><p>Review the submission before sending it to OSAS. You can add rooms after the accommodation is verified.</p></div>
          <fieldset><legend>Included amenities <span class="optional">Optional</span></legend><div class="amenity-grid"><button v-for="amenity in amenitiesOptions" :key="amenity.value" type="button" :class="{ active: form.amenities.includes(amenity.value) }" :aria-pressed="form.amenities.includes(amenity.value)" @click="toggleAmenity(amenity.value)"><IconifyIcon :icon="amenity.icon" width="19" aria-hidden="true" /> {{ amenity.label }}</button></div></fieldset>
          <fieldset><legend>House rules <span class="optional">Optional</span></legend><div v-if="form.rules.length" class="rules-list"><div v-for="(rule, index) in form.rules" :key="`${rule}-${index}`"><span>{{ rule }}</span><button type="button" :aria-label="`Remove rule: ${rule}`" @click="removeRule(index)"><IconifyIcon icon="lucide:x" width="16" aria-hidden="true" /></button></div></div><div class="rule-entry"><q-input v-model="newRule" outlined dense placeholder="e.g. No smoking indoors" @keyup.enter="addRule" /><button type="button" @click="addRule">Add rule</button></div></fieldset>
          <section class="review-card" aria-labelledby="review-heading"><h3 id="review-heading">Submission review</h3><div><span>Accommodation type</span><strong>{{ accommodationTypeLabel }}</strong></div><div><span>Location pin</span><strong>{{ form.latitude != null ? 'Set' : 'Not set' }}</strong></div><div><span>Exterior photos</span><strong>{{ form.exteriorImages.length }}</strong></div><div><span>Required permits</span><strong>{{ submittedPermitCount }} of {{ permitRequirements.length }}</strong></div><p v-if="!form.exteriorImages.length">Exterior photos are optional but help OSAS identify the accommodation.</p><p>Rooms and shared facilities unlock once OSAS approves this accommodation.</p></section>
        </section>
        </q-step>
      </q-stepper>
          <footer class="setup-footer"><button v-if="currentStep > 1" type="button" class="back-button" :disabled="saving" @click="currentStep -= 1">Go Back</button><button v-if="currentStep < steps.length" type="button" class="next-button" @click="goNext">Next Step <IconifyIcon icon="lucide:arrow-right" width="17" aria-hidden="true" /></button><button v-else type="button" class="next-button" :disabled="saving" @click="saveAccommodation"><IconifyIcon icon="lucide:send" width="17" aria-hidden="true" /> {{ saving ? 'Submitting' : 'Submit to OSAS' }}</button></footer>
    </main>
  </q-page>
</template>

<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref } from 'vue'
import { Icon as IconifyIcon } from '@iconify/vue'
import { useQuasar } from 'quasar'
import { useRouter } from 'vue-router'
import mapboxgl from 'mapbox-gl'
import 'mapbox-gl/dist/mapbox-gl.css'
import { useLandlordStore } from '@/stores/landlord'
import PhotoPicker from '@/modules/landlord/components/AccommodationPhotoPicker.vue'

type RoomStatus = 'available' | 'occupied' | 'maintenance'
interface Photo { file: File; preview: string }
interface LocationResult { id: string; name: string; address: string; longitude: number; latitude: number }
type PermitType = 'sanitary_permit' | 'fire_safety' | 'business_permit' | 'building_permit'
const router = useRouter(); const $q = useQuasar(); const landlordStore = useLandlordStore(); const currentStep = ref(1); const saving = ref(false); const newRule = ref(''); const stepError = ref<Record<string, string>>({})
const steps = [{ value: 1 }, { value: 2 }, { value: 3 }, { value: 4 }, { value: 5 }]
const accommodationTypes = [{ label: 'Boarding house', value: 'boarding_house' }, { label: 'Dormitory / residence hall', value: 'residence_hall' }, { label: 'Apartment building', value: 'apartment_building' }, { label: 'Apartment unit', value: 'apartment_unit' }, { label: 'House', value: 'house' }, { label: 'Condominium unit', value: 'condominium_unit' }, { label: 'Bedspace facility', value: 'bedspace_facility' }, { label: 'Other', value: 'other' }]
const permitRequirements: { type: PermitType; label: string; description: string; icon: string }[] = [{ type: 'sanitary_permit', label: 'Sanitary permit', description: 'Current local health or sanitary clearance.', icon: 'lucide:clipboard-check' }, { type: 'fire_safety', label: 'Fire safety permit', description: 'Current fire safety inspection certificate.', icon: 'lucide:flame' }, { type: 'business_permit', label: 'Business permit', description: 'Current local business permit for the accommodation.', icon: 'lucide:briefcase-business' }, { type: 'building_permit', label: 'Building permit', description: 'Building or occupancy permit for the premises.', icon: 'lucide:building' }]
const genderOptions = [{ label: 'Boys only', value: 'boys' }, { label: 'Girls only', value: 'girls' }, { label: 'Co-ed', value: 'coed' }]; const amenitiesOptions = [{ label: 'Wi-Fi', value: 'wifi', icon: 'lucide:wifi' }, { label: 'Water', value: 'water', icon: 'lucide:droplets' }, { label: 'Electricity', value: 'electric', icon: 'lucide:zap' }, { label: 'Air conditioning', value: 'aircon', icon: 'lucide:wind' }]
const form = ref({ name: '', accommodationType: '', customAccommodationType: '', genderPolicy: '', address: '', latitude: null as number | null, longitude: null as number | null, totalFloors: null as number | null, description: '', exteriorImages: [] as Photo[], amenities: [] as string[], rules: [] as string[], permits: { sanitary_permit: null as File | null, fire_safety: null as File | null, business_permit: null as File | null, building_permit: null as File | null } })
const locationMap = ref<HTMLElement | null>(null); const locationResults = ref<LocationResult[]>([]); const locationSearchLoading = ref(false); let map: mapboxgl.Map | null = null; let locationMarker: mapboxgl.Marker | null = null; let locationSearchTimer: ReturnType<typeof setTimeout> | undefined
const accommodationTypeLabel = computed(() => form.value.accommodationType === 'other' ? form.value.customAccommodationType || 'Other' : accommodationTypes.find((item) => item.value === form.value.accommodationType)?.label || 'Not set'); const submittedPermitCount = computed(() => permitRequirements.filter((permit) => Boolean(form.value.permits[permit.type])).length)
function onPhotosSelected(event: Event, target: Photo[]) { const input = event.target as HTMLInputElement; for (const file of Array.from(input.files || [])) { if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) { $q.notify({ type: 'negative', message: 'Use JPG, PNG, or WebP images only.', position: 'top' }); continue }; if (file.size > 5 * 1024 * 1024) { $q.notify({ type: 'negative', message: 'Each photo must be 5 MB or smaller.', position: 'top' }); continue }; target.push({ file, preview: URL.createObjectURL(file) }) }; input.value = '' }; function removePhoto(target: Photo[], index: number) { const [photo] = target.splice(index, 1); if (photo) URL.revokeObjectURL(photo.preview) }
function toggleAmenity(amenity: string) { const index = form.value.amenities.indexOf(amenity); if (index === -1) form.value.amenities.push(amenity); else form.value.amenities.splice(index, 1) }; function addRule() { const rule = newRule.value.trim(); if (rule && !form.value.rules.includes(rule)) form.value.rules.push(rule); newRule.value = '' }; function removeRule(index: number) { form.value.rules.splice(index, 1) }
function validateStep(step: number) { const errors: Record<string, string> = {}; if (step === 1) { if (!form.value.name.trim()) errors.name = 'Enter the accommodation name.'; if (!form.value.accommodationType) errors.accommodationType = 'Choose an accommodation type.'; if (form.value.accommodationType === 'other' && !form.value.customAccommodationType.trim()) errors.accommodationType = 'Describe the accommodation type.'; if (!form.value.genderPolicy) errors.genderPolicy = 'Choose who can stay.'; if (!form.value.description.trim()) errors.description = 'Add a short description.' } if (step === 3) { if (!form.value.address.trim()) errors.address = 'Enter the full address.'; if (form.value.latitude == null || form.value.longitude == null) errors.address = 'Select an address or place the pin on the map.' } if (step === 4 && submittedPermitCount.value !== permitRequirements.length) errors.permits = 'Upload all four required permits before submitting for OSAS verification.'; stepError.value = errors; return !Object.keys(errors).length }
function setLocationPin(longitude: number, latitude: number, zoom = 16) { form.value.longitude = longitude; form.value.latitude = latitude; if (!map) return; if (!locationMarker) locationMarker = new mapboxgl.Marker({ color: '#00897b' }); locationMarker.setLngLat([longitude, latitude]).addTo(map); map.flyTo({ center: [longitude, latitude], zoom, essential: true }) }
function initializeLocationMap() { if (!locationMap.value || map) return; mapboxgl.accessToken = import.meta.env.VITE_MAPBOX_TOKEN || ''; if (!mapboxgl.accessToken) return; const longitude = form.value.longitude ?? 121.720; const latitude = form.value.latitude ?? 16.710; map = new mapboxgl.Map({ container: locationMap.value, style: 'mapbox://styles/mapbox/streets-v12', center: [longitude, latitude], zoom: form.value.longitude == null ? 13 : 16 }); map.addControl(new mapboxgl.NavigationControl({ showCompass: false }), 'top-right'); map.on('load', () => { if (form.value.longitude != null && form.value.latitude != null) setLocationPin(form.value.longitude, form.value.latitude) }); map.on('click', (event) => setLocationPin(event.lngLat.lng, event.lngLat.lat)) }
function searchLocation() { if (locationSearchTimer) clearTimeout(locationSearchTimer); const query = form.value.address.trim(); locationResults.value = []; if (query.length < 3 || !import.meta.env.VITE_MAPBOX_TOKEN) return; locationSearchTimer = setTimeout(async () => { locationSearchLoading.value = true; try { const response = await fetch(`https://api.mapbox.com/search/geocode/v6/forward?q=${encodeURIComponent(query)}&limit=4&access_token=${import.meta.env.VITE_MAPBOX_TOKEN}`); if (!response.ok) throw new Error('Mapbox search failed.'); const payload = await response.json(); locationResults.value = (payload.features ?? []).flatMap((feature: any) => { const coordinates = feature.geometry?.coordinates; return Array.isArray(coordinates) && coordinates.length >= 2 ? [{ id: feature.id, name: feature.properties?.name || feature.place_formatted || 'Selected location', address: feature.place_formatted || feature.properties?.full_address || '', longitude: coordinates[0], latitude: coordinates[1] }] : [] }) } catch { locationResults.value = [] } finally { locationSearchLoading.value = false } }, 350) }
function selectLocation(result: LocationResult) { form.value.address = result.address || result.name; locationResults.value = []; setLocationPin(result.longitude, result.latitude) }
function goNext() { if (validateStep(currentStep.value)) { currentStep.value += 1; if (currentStep.value === 3) void nextTick(initializeLocationMap) } }; function handleClose() { void router.push('/landlord/properties') }
async function saveAccommodation() { if (!validateStep(3)) { currentStep.value = 3; return }; if (!validateStep(4)) { currentStep.value = 4; return }; saving.value = true; try { const success = await landlordStore.addProperty({ name: form.value.name.trim(), accommodationType: form.value.accommodationType === 'other' ? form.value.customAccommodationType.trim() : form.value.accommodationType, address: form.value.address.trim(), latitude: form.value.latitude, longitude: form.value.longitude, description: form.value.description.trim(), totalFloors: form.value.totalFloors, genderPolicy: form.value.genderPolicy, amenities: form.value.amenities, rules: form.value.rules, exteriorImages: form.value.exteriorImages.map((photo) => photo.file), permits: permitRequirements.map((permit) => ({ type: permit.type, file: form.value.permits[permit.type] })) }); if (!success) throw new Error('Unable to submit the accommodation.'); $q.notify({ type: 'positive', message: 'Accommodation submitted to OSAS. Rooms and shared facilities unlock after approval.', position: 'top' }); void router.push('/landlord/properties') } catch (error) { $q.notify({ type: 'negative', message: error instanceof Error ? error.message : 'Unable to submit the accommodation.', position: 'top' }) } finally { saving.value = false } }
onBeforeUnmount(() => { if (locationSearchTimer) clearTimeout(locationSearchTimer); map?.remove() })
</script>

<style scoped>
