tent > label,.facility-card label,.room-card > label,.private-facility label { display: grid; gap: 6px; color: var(--m-text); font-size: 12px; font-weight: 750; }.step-content label > span,.step-content legend > span { color: var(--m-danger); }.step-content .optional { color: var(--m-muted); font-weight: 600; }.step-content fieldset { margin: 0; padding: 0; border: 0; }.step-content legend { margin-bottom: 8px; color: var(--m-text); font-size: 12px; font-weight: 750; }.choice-grid,.amenity-grid { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 8px; }.choice-grid button,.amenity-grid button { min-height: 44px; padding: 7px; border: 1px solid var(--m-border); border-radius: 8px; background: var(--m-surface); color: var(--m-text); font-size: 12px; font-weight: 750; }.choice-grid button.active,.amenity-grid button.active,.room-type-grid button.active { border-color: var(--m-primary); background: var(--m-primary-soft); color: var(--m-primary-dark); }.amenity-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }.amenity-grid button { display: flex; align-items: center; justify-content: center; gap: 7px; }.facility-card,.room-card,.private-facility,.review-card { display: grid; gap: 12px; padding: 14px; border: 1px solid var(--m-border); border-radius: 12px; background: var(--m-surface); }.room-card { gap: 14px; border-top: 3px solid var(--m-primary); }.private-facility { padding: 12px; background: var(--m-bg); }.card-heading,.subsection-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; }.card-heading strong,.subsection-heading strong { display: block; color: var(--m-ink); font-size: 13px; font-weight: 800; }.room-index { display: block; margin-bottom: 3px; color: var(--m-primary-dark); font-size: 10px; font-weight: 850; letter-spacing: .06em; text-transform: uppercase; }.card-heading small,.subsection-heading span { display: block; margin-top: 2px; color: var(--m-muted); font-size: 11px; font-weight: 600; }.text-danger,.small-add { display: inline-flex; min-height: 32px; align-items: center; gap: 4px; padding: 0 4px; border: 0; background: transparent; font-size: 11px; font-weight: 800; }.text-danger { color: var(--m-danger); }.small-add { color: var(--m-primary-dark); }.room-type-grid { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 8px; }.room-type-grid button { display: grid; min-height: 58px; align-content: center; gap: 3px; padding: 7px; border: 1px solid var(--m-border); border-radius: 8px; background: var(--m-surface); color: var(--m-text); text-align: left; }.room-type-grid strong { font-size: 12px; font-weight: 800; }.room-type-grid small { color: var(--m-muted); font-size: 10px; font-weight: 650; }.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }.form-grid--single { grid-template-columns: minmax(0,1fr) minmax(0,1fr); }.capacity-note { display: flex; align-items: center; gap: 8px; min-height: 40px; padding: 8px 10px; border: 1px solid var(--m-primary-soft); border-radius: 8px; background: var(--m-primary-soft); color: var(--m-primary-dark); font-size: 11px; line-height: 1.35; }.capacity-note strong { font-weight: 850; }.subsection { display: grid; gap: 10px; padding-top: 2px; }.add-outline { display: flex; min-height: 44px; align-items: center; justify-content: center; gap: 7px; border: 1px dashed var(--m-primary); border-radius: 8px; background: var(--m-primary-soft); color: var(--m-primary-dark); font-size: 13px; font-weight: 800; }.rules-list { display: grid; gap: 7px; margin-bottom: 9px; }.rules-list > div { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 9px 10px; border: 1px solid var(--m-border); border-radius: 8px; background: var(--m-surface); color: var(--m-text); font-size: 12px; }.rules-list button { display: grid; width: 28px; height: 28px; place-items: center; border: 0; border-radius: 5px; background: transparent; color: var(--m-danger); }.rule-entry { display: grid; grid-template-columns: minmax(0,1fr) auto; gap: 8px; }.rule-entry button { min-height: 40px; padding: 0 12px; border: 0; border-radius: 8px; background: var(--m-primary-dark); color: #fff; font-size: 12px; font-weight: 800; }.review-card h3 { margin: 0 0 2px; color: var(--m-ink); font-size: 15px; font-weight: 800; }.review-card > div { display: flex; justify-content: space-between; gap: 16px; color: var(--m-muted); font-size: 12px; }.review-card strong { color: var(--m-ink); text-align: right; }.review-card p { margin: 0; color: var(--m-warning); font-size: 11px; line-height: 1.4; }.field-error { margin: -6px 0 0; color: var(--m-danger); font-size: 12px; font-weight: 650; }.setup-footer { display: flex; justify-content: space-between; gap: 12px; margin-top: 24px; padding-top: 16px; border-top: 1px solid var(--m-border); }.back-button,.next-button { min-height: 44px; padding: 0 16px; border-radius: 8px; font-size: 13px; font-weight: 800; }.back-button { border: 1px solid var(--m-border); background: var(--m-surface); color: var(--m-text); }.next-button { display: inline-flex; align-items: center; gap: 7px; border: 0; background: var(--m-primary-dark); color: #fff; }.back-button:disabled,.next-button:disabled { opacity: .55; }.close-button:focus-visible,.stepper button:focus-visible,.choice-grid button:focus-visible,.amenity-grid button:focus-visible,.room-type-grid button:focus-visible,.add-outline:focus-visible,.setup-footer button:focus-visible,.text-danger:focus-visible,.small-add:focus-visible { outline: 2px solid var(--m-primary); outline-offset: 2px; } @media (max-width:390px) { .room-type-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }.form-grid,.form-grid--single { grid-template-columns: 1fr; } } @media (max-width:360px) { .stepper small { display: none; }.choice-grid { grid-template-columns: 1fr; } }
</style>

<style scoped>
/* Edge-to-edge workflow surface: form content uses the available page width. */
.setup-page { min-height: 100%; background: var(--m-bg); }
